export interface HtmlEditorWorkspaceProps {
  pageId: string
  storedContent: string
  /** Active source subfile; null shows only the rendered preview. */
  sourceField: 'html' | 'css' | 'javascript' | null
  /** Returns from a source subfile to the rendered preview. */
  onExitSource?: () => void
  /** Switches the active HTML source subfile (or back to preview). */
  onSourceFieldChange?: (field: 'preview' | 'html' | 'css' | 'javascript') => void
  /** Persists editor content and syncs the pages list. */
  onSaveContent?: (id: string, content: string) => Promise<boolean>
  /** Returns to the pages dashboard from recovery UIs. */
  onBack?: () => void
  /** Hands the page-level toolbar node up so the parent hosts it in the shared
   *  toolbar row directly under the tab strip (matching the Rich page layout). */
  onToolbarReady?: (node: ReactNode | null) => void
  onFlushRef?: (fn: (() => Promise<boolean>) | null) => void
  onSaveStateChange?: (state: {
    isDirty: boolean
    /** Reused from the status bar so the two cannot drift apart. */
    saveState: StatusSaveState
    error?: string | null
  }) => void
  /** Lifts caret/selection + format-error up to the global status bar. */
  onEditorStatusChange?: (status: EditorStatus) => void
}

type ContentField = 'html' | 'css' | 'javascript'

const FIELD_LABELS: Record<ContentField, keyof typeof UI_TEXT> = {
  html: 'editorPaneLabelHtml',
  css: 'editorPaneLabelCss',
  javascript: 'editorPaneLabelJs'
}

